import numpy as np
from scipy.optimize import minimize

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
    except ImportError:
        raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.random.uniform(-1, 1, dim)
        # Adaptive population: ensures robust diversity for high dimensions while scaling with budget
        self.pop_size = max(20, int(self.budget / 8))
        self.rng = np.random.default_rng(42)

    def _evaluate(self, x, func):
        if self.evals >= self.budget: 
            return float('inf')
        x_clean = np.clip(x, -1.0, 1.0)
        f = func(x_clean)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x_clean.copy()
        return f

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        # LHS Initialization
        pop = _lhs(n_samples=self.pop_size, n_dim=self.dim)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)

        fitness = np.full(self.pop_size, float('inf'))
        for i in range(self.pop_size):
            fitness[i] = self._evaluate(pop[i], func)
            if self.evals >= self.budget: return self.best_f, self.best_x

        F, CR = 0.5, 0.9
        # Calculate generations to maximize budget utilization
        max_gen = max(5, int(self.budget / self.pop_size))

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            for i in range(self.pop_size):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(self.pop_size, 3, replace=False)
                while np.any(idxs == i):
                    idxs = self.rng.choice(self.pop_size, 3, replace=False)
                r1, r2, r3 = idxs

                mutant = pop[r1] + F * (pop[r2] - pop[r3])

                # Enhanced gradient guidance with safer scaling for stability
                if grad_func is not None:
                    g = grad_func(pop[i])
                    if g.shape[0] == 18:
                        res_vec = np.zeros(self.dim)
                        res_vec[:18] = g * 0.2  # Increased influence for faster convergence
                        mutant -= res_vec

                mutant = np.clip(mutant, -1.0, 1.0)

                cr_mask = self.rng.random(self.dim) < CR
                trial = np.where(cr_mask, mutant, pop[i])

                f_trial = self._evaluate(trial, func)
                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial

        # Adaptive local search with dynamic iteration budget
        if grad_func is not None and self.evals < self.budget * 0.95:
            fixed_cats = self.best_x[18:24].copy()
            def cost_wrap(x_c): return self._evaluate(np.concatenate([x_c, fixed_cats]), func)
            def grad_wrap(x_c): return grad_func(np.concatenate([x_c, fixed_cats]))

            rem_budget = self.budget - self.evals
            safe_maxiter = min(30, rem_budget // 8)
            if safe_maxiter > 0:
                res = minimize(cost_wrap, self.best_x[:18], jac=grad_wrap, method='L-BFGS-B', 
                               bounds=[(-1.0, 1.0)]*18, options={'maxiter': safe_maxiter, 'ftol': 1e-4})
                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([res.x, fixed_cats])

        return self.best_f, self.best_x
